/* ---- db ---- */




// numeric/bigint come back as strings by default — we want numbers for money maths
pg.types.setTypeParser(20, v => parseInt(v, 10));      // int8
pg.types.setTypeParser(1700, v => parseFloat(v));      // numeric
pg.types.setTypeParser(1082, v => v);                  // date → keep as 'YYYY-MM-DD'

function sslConfig() {
  if (process.env.PGSSL !== 'true') return undefined;
  if (process.env.PGSSL_INSECURE === 'true') {
    console.warn('WARNING: PGSSL_INSECURE=true — the database certificate is NOT being verified.');
    return { rejectUnauthorized: false };
  }
  const ca = process.env.PGSSLROOTCERT;
  return ca ? { rejectUnauthorized: true, ca: fs.readFileSync(ca, 'utf8') } : { rejectUnauthorized: true };
}
const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: sslConfig(),
  max: Number(process.env.PG_POOL || 10),
  idleTimeoutMillis: 30000
});

const q = (text, params) => pool.query(text, params);
async function tx(fn) {
  const c = await pool.connect();
  try {
    await c.query('BEGIN');
    const r = await fn(c);
    await c.query('COMMIT');
    return r;
  } catch (e) {
    await c.query('ROLLBACK').catch(() => { });
    throw e;
  } finally { c.release(); }
}

async function migrate() {
  await q(SCHEMA_SQL);
}

/** Issue the next number atomically. Nothing else can hand out the same one. */
async function nextCounter(client, key, fallbackStart) {
  const r = await client.query(
    `INSERT INTO counters(key, value) VALUES ($1, $2)
     ON CONFLICT (key) DO UPDATE SET value = counters.value + 1
     RETURNING value`, [key, fallbackStart]);
  return r.rows[0].value;
}

async function audit(client, user, action, entity, entityId, detail = {}) {
  const c = client || pool;
  await c.query(
    `INSERT INTO audit_log(user_id, username, action, entity, entity_id, detail)
     VALUES ($1,$2,$3,$4,$5,$6)`,
    [user?.id || null, user?.username || 'system', action, entity, String(entityId ?? ''), JSON.stringify(detail)]);
}

/* ---------- money helpers: rupees at the edge, paise inside ---------- */
const toPaise = (rupees) => Math.round((Number(rupees) || 0) * 100);
const toRupees = (paise) => Math.round(Number(paise) || 0) / 100;

/* ---- calc ---- */
/** Single source of truth for money. Everything in paise, integers only.
 *  The server recomputes this on every save — client totals are never trusted.
 *
 *  GST comes in two flavours, chosen per procedure:
 *
 *    gst_incl = false  "GST extra"     the rate is pre-tax; GST is ADDED on top,
 *                                      so the patient pays more than the rate.
 *    gst_incl = true   "GST included"  the rate ALREADY contains GST; nothing is
 *                                      added. The tax is extracted from the price
 *                                      for the tax invoice and the patient pays
 *                                      exactly the rate that was quoted.
 *
 *  Extraction for an inclusive line at rate r%:  tax = net * r / (100 + r)
 *
 *  Returned:
 *    tax_paise      total GST on the bill (added + extracted) — what a tax
 *                   invoice must declare
 *    tax_add_paise  the part that increases what the patient pays
 *    tax_inc_paise  the part already sitting inside the quoted prices
 *    total_paise    sub - disc + tax_add_paise
 */
function calcInvoice(items, discType, discValue, gstOn) {
  let sub = 0;
  const out = items.map(it => {
    const qty = Math.max(0, Number(it.qty) || 0);
    const rate = Math.max(0, Math.round(Number(it.rate_paise) || 0));
    const gross = Math.round(qty * rate);
    let d = Math.round(Number(it.disc_paise) || 0);
    if (d < 0) d = 0;
    if (d > gross) d = gross;
    const amount = gross - d;
    sub += amount;
    return { ...it, qty, rate_paise: rate, disc_paise: d, amount_paise: amount };
  });

  let disc = 0;
  if (discType === 'pct') {
    let pv = Number(discValue) || 0;
    pv = Math.min(100, Math.max(0, pv));
    disc = Math.round(sub * pv / 100);
  } else {
    disc = Math.round(Number(discValue) || 0);          // discValue is paise when type = amt
    if (disc < 0) disc = 0;
  }
  if (disc > sub) disc = sub;

  // GST on the post-discount value, bill discount apportioned pro-rata
  let taxAdd = 0, taxInc = 0;
  if (gstOn && sub > 0) {
    for (const it of out) {
      if (!it.taxable) continue;
      const r = Number(it.gst_rate) || 0;
      if (r <= 0) continue;
      const net = it.amount_paise - Math.round(disc * it.amount_paise / sub);
      if (net <= 0) continue;
      // Default to INCLUSIVE when the flag is absent (legacy rows). That is the
      // safe direction: the patient is never charged more than the quoted price.
      const incl = it.gst_incl === undefined || it.gst_incl === null ? true : !!it.gst_incl;
      if (incl) taxInc += Math.round(net * r / (100 + r));   // carved out of the price
      else taxAdd += Math.round(net * r / 100);              // added on top
    }
  }
  return {
    items: out,
    sub_paise: sub,
    disc_paise: disc,
    tax_paise: taxAdd + taxInc,
    tax_add_paise: taxAdd,
    tax_inc_paise: taxInc,
    total_paise: sub - disc + taxAdd
  };
}

/* ---- auth ---- */


const SECRET = process.env.JWT_SECRET;
const COOKIE = 'hk_session';
const MAXAGE = Number(process.env.SESSION_HOURS || 12) * 3600 * 1000;

const hash = (pw) => bcrypt.hash(pw, 12);
const verify = (pw, h) => bcrypt.compare(pw, h);

function issue(res, user) {
  const token = jwt.sign(
    { id: user.id, u: user.username, role: user.role, e: Number(user.token_epoch || 0) },
    SECRET, { algorithm: 'HS256', expiresIn: Math.floor(MAXAGE / 1000) });
  res.cookie(COOKIE, token, {
    httpOnly: true,
    sameSite: 'strict',
    secure: process.env.NODE_ENV === 'production',
    maxAge: MAXAGE,
    path: '/'
  });
}
const clear = (res) => res.clearCookie(COOKIE, { path: '/' });
/** verify-and-read a token; used to know whose epoch to bump on logout */
const jwtDecode = (t) => { try { return jwt.verify(t, SECRET, { algorithms: ['HS256'] }); } catch { return null; } };

async function auth(req, res, next) {
  const t = req.cookies?.[COOKIE];
  if (!t) return res.status(401).json({ error: 'Not signed in' });
  let p;
  try { p = jwt.verify(t, SECRET, { algorithms: ['HS256'] }); }
  catch { clear(res); return res.status(401).json({ error: 'Session expired' }); }
  const { rows } = await q('SELECT id, username, role, active, full_name, token_epoch FROM users WHERE id=$1', [p.id]);
  if (!rows[0] || !rows[0].active) { clear(res); return res.status(401).json({ error: 'Account disabled' }); }
  // a password change or admin reset bumps token_epoch, which instantly kills older sessions
  if (Number(rows[0].token_epoch || 0) !== Number(p.e || 0)) {
    clear(res); return res.status(401).json({ error: 'Session ended — the password was changed' });
  }
  req.user = rows[0];
  next();
}
function admin(req, res, next) {
  if (req.user?.role !== 'admin') return res.status(403).json({ error: 'Admin access only' });
  next();
}
/** cheap CSRF defence: browsers cannot set this header cross-origin without CORS approval */
function csrf(req, res, next) {
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) return next();
  if (req.get('X-Requested-With') !== 'hk') return res.status(403).json({ error: 'Bad request origin' });
  next();
}

async function logLogin(user, ok, ip) {
  await audit(null, ok ? user : { id: null, username: user?.username || '?' },
    ok ? 'login' : 'login_failed', 'user', user?.id || '', { ip });
}

