async function seedIfEmpty() {
  const { rows: [{ count }] } = await q('SELECT count(*)::int AS count FROM users');
  const created = { admin: null };

  if (count === 0) {
    const pw = process.env.ADMIN_PASSWORD || 'ChangeMe@123';
    const h = await hash(pw);
    await q(`INSERT INTO users(username, pass_hash, full_name, role, must_change)
             VALUES ($1,$2,$3,'admin',$4)`,
      [(process.env.ADMIN_USER || 'admin').toLowerCase(), h, 'Administrator', true]);
    created.admin = process.env.ADMIN_USER || 'admin';
  }

  const { rows: [d] } = await q('SELECT count(*)::int AS c FROM doctors');
  if (d.c === 0) {
    await q(`INSERT INTO doctors(name, spec, role_line, reg_no, sign_title)
             VALUES ('Dr. Sijo P. Mathew MDS','(Conservative Dentistry & Endodontics)','Chief Dental Surgeon & Endodontist','8982','Chief Clinic Director')`);
  }

  const { rows: [p] } = await q('SELECT count(*)::int AS c FROM procedures');
  if (p.c === 0) {
    const vals = [], params = [];
    SEED.forEach((r, i) => {
      const b = i * 5;
      vals.push(`($${b + 1},$${b + 2},$${b + 3},$${b + 4},$${b + 5})`);
      params.push(r[0], CATS[r[1]], toPaise(r[2]), !!r[3], i);
    });
    await q(`INSERT INTO procedures(name, category, price_paise, per_tooth, sort) VALUES ${vals.join(',')}`, params);
  }

  const { rows: [m] } = await q(`SELECT count(*)::int AS c FROM app_meta WHERE key='settings'`);
  if (m.c === 0) {
    const { rows: [doc] } = await q('SELECT id FROM doctors ORDER BY id LIMIT 1');
    await q(`INSERT INTO app_meta(key, value) VALUES ('settings', $1)`,
      [JSON.stringify({ ...DEFAULT_SETTINGS, defaultDoctorId: doc?.id || null })]);
  }
  // bill numbers continue from the paper register
  await q(`INSERT INTO counters(key, value) VALUES ('bill_no', $1) ON CONFLICT DO NOTHING`,
    [Number(process.env.START_BILL_NO || 168)]);
  await q(`INSERT INTO counters(key, value) VALUES ('reg_no', $1) ON CONFLICT DO NOTHING`,
    [Number(process.env.START_REG_NO || 12681)]);
  return created;
}

